import sys

def pick(nums, t):
    drop = len(nums) - t
    st = []
    for d in nums:
        while drop and st and st[-1] < d:
            st.pop()
            drop -= 1
        st.append(d)
    return st[:t]

def merge(a, b):
    out = []
    i = j = 0
    la, lb = len(a), len(b)
    while i < la or j < lb:
        if a[i:] >= b[j:]:
            out.append(a[i]); i += 1
        else:
            out.append(b[j]); j += 1
    return out

def main():
    data = sys.stdin.read().split()
    m, n, k = int(data[0]), int(data[1]), int(data[2])
    a = [int(x) for x in data[3:3 + m]]
    b = [int(x) for x in data[3 + m:3 + m + n]]
    best = None
    for i in range(max(0, k - n), min(k, m) + 1):
        cand = merge(pick(a, i), pick(b, k - i))
        if best is None or cand > best:
            best = cand
    print(''.join(map(str, best)))

main()

