a = [int(x) for x in data[3:3 + m]]
b = [int(x) for x in data[3 + m:3 + m + n]]

def interleavings(x, y):
    if not x:
        yield list(y)
        return
    if not y:
        yield list(x)
        return
    for rest in interleavings(x[1:], y):
        yield [x[0]] + rest
    for rest in interleavings(x, y[1:]):
        yield [y[0]] + rest

best = None
for i in range(0, k + 1):
    if i > m or k - i > n:
        continue
    for s1 in combinations(a, i):
        for s2 in combinations(b, k - i):
            for r in interleavings(list(s1), list(s2)):
                if best is None or r > best:
                    best = r
print(''.join(map(str, best)))

